/**
 * Mitosis runtime helpers for React.
 * useLocalProxy is generated by the Mitosis compiler for components with useState.
 * It provides a mutable proxy that triggers re-renders on property changes.
 */

// deno-lint-ignore-file no-explicit-any
import { useCallback, useRef, useState as useReactState } from 'npm:react@^19.2.0';

export function useLocalProxy<T extends Record<string, any>>(initialState: T): T {
  const [, setTick] = useReactState(0);
  const stateRef = useRef<T>({ ...initialState });

  const forceUpdate = useCallback(() => {
    setTick((t: number) => t + 1);
  }, []);

  const proxyRef = useRef<T | null>(null);

  if (!proxyRef.current) {
    proxyRef.current = new Proxy(stateRef.current, {
      set(target, prop, value) {
        const key = prop as keyof T;
        if (target[key] !== value) {
          target[key] = value;
          forceUpdate();
        }
        return true;
      },
      get(target, prop) {
        return target[prop as keyof T];
      },
    });
  }

  return proxyRef.current;
}
